#!/usr/bin/env node
// Generates typed bridge bindings for TS and Swift from bridge/schema.json.
// Usage: node scripts/gen-bridge.mjs [--check]
//   --check  exit 1 if generated files are out of date (used in CI).
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const schemaPath = join(root, 'bridge/schema.json');
const tsOut = join(root, 'editor/src/bridge/schema.gen.ts');
const swiftOut = join(root, 'mac/Ocelot/Bridge/BridgeSchema.gen.swift');
const check = process.argv.includes('--check');

const schema = JSON.parse(readFileSync(schemaPath, 'utf8'));
const typeNames = new Set(Object.keys(schema.types));
const PRIMS = new Set(['string', 'number', 'integer', 'boolean', 'json']);

function parseType(raw, where) {
  let t = raw;
  const optional = t.endsWith('?');
  if (optional) t = t.slice(0, -1);
  const array = t.endsWith('[]');
  if (array) t = t.slice(0, -2);
  if (!PRIMS.has(t) && !typeNames.has(t)) {
    throw new Error(`Unknown type "${raw}" at ${where}`);
  }
  return { base: t, array, optional };
}

const methodEntries = (group) =>
  Object.entries(schema[group]).filter(([k]) => !k.startsWith('$'));

for (const group of ['host', 'editor']) {
  for (const [name, m] of methodEntries(group)) {
    if (!name.startsWith(`${group}.`)) throw new Error(`Method ${name} must start with "${group}."`);
    parseType(m.params, `${name}.params`);
    parseType(m.result, `${name}.result`);
  }
}

// A method enum (e.g. HostMethods.DocumentChanged) must not shadow a schema type,
// or `typealias Params = DocumentChanged` inside it would refer to the enum itself.
for (const group of ['host', 'editor']) {
  for (const [name] of methodEntries(group)) {
    const short = name.slice(group.length + 1);
    const pascalName = short.charAt(0).toUpperCase() + short.slice(1);
    if (typeNames.has(pascalName)) {
      throw new Error(`Method "${name}" maps to Swift enum ${pascalName}, which collides with type "${pascalName}". Rename the type (e.g. ${pascalName}Params).`);
    }
  }
}

const header = (c) =>
  `${c} GENERATED by scripts/gen-bridge.mjs from bridge/schema.json. Do not edit.\n`;

// ---------- TypeScript ----------
function tsType({ base, array }) {
  const b = { string: 'string', number: 'number', integer: 'number', boolean: 'boolean', json: 'JsonValue' }[base] ?? base;
  return array ? `${b}[]` : b;
}

let ts = header('//');
ts += `/* eslint-disable */\n\n`;
ts += `export const BRIDGE_SCHEMA_VERSION = ${schema.version};\n`;
ts += `export const BRIDGE_MESSAGE_HANDLER = ${JSON.stringify(schema.names.messageHandler)};\n`;
ts += `export const BRIDGE_EDITOR_GLOBAL = ${JSON.stringify(schema.names.editorGlobal)};\n\n`;
ts += `export type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };\n\n`;
ts += `export const BRIDGE_ERROR_CODES = ${JSON.stringify(schema.errorCodes)} as const;\n`;
ts += `export type BridgeErrorCode = (typeof BRIDGE_ERROR_CODES)[number];\n\n`;
for (const [name, fields] of Object.entries(schema.types)) {
  const entries = Object.entries(fields);
  if (entries.length === 0) {
    ts += `export type ${name} = Record<string, never>;\n\n`;
    continue;
  }
  ts += `export interface ${name} {\n`;
  for (const [f, raw] of entries) {
    const t = parseType(raw, `${name}.${f}`);
    ts += `  ${f}${t.optional ? '?' : ''}: ${tsType(t)};\n`;
  }
  ts += `}\n\n`;
}
for (const group of ['host', 'editor']) {
  const iface = group === 'host' ? 'HostMethods' : 'EditorMethods';
  ts += `export interface ${iface} {\n`;
  for (const [name, m] of methodEntries(group)) {
    ts += `  '${name}': { params: ${tsType(parseType(m.params, name))}; result: ${tsType(parseType(m.result, name))} };\n`;
  }
  ts += `}\n\n`;
  ts += `export const ${group.toUpperCase()}_METHOD_NAMES = ${JSON.stringify(methodEntries(group).map(([n]) => n))} as const;\n\n`;
}
ts += `export interface BridgeRequest {\n  v: typeof BRIDGE_SCHEMA_VERSION;\n  id: string;\n  method: string;\n  params: unknown;\n}\n\n`;
ts += `export interface BridgeErrorPayload {\n  code: BridgeErrorCode;\n  message: string;\n  data?: JsonValue;\n}\n\n`;
ts += `export type BridgeResponse =\n  | { v: typeof BRIDGE_SCHEMA_VERSION; id: string; ok: true; result: unknown }\n  | { v: typeof BRIDGE_SCHEMA_VERSION; id: string; ok: false; error: BridgeErrorPayload };\n`;

// ---------- Swift ----------
function swiftType({ base, array, optional }) {
  const b = { string: 'String', number: 'Double', integer: 'Int', boolean: 'Bool', json: 'JSONValue' }[base] ?? base;
  return `${array ? `[${b}]` : b}${optional ? '?' : ''}`;
}
const pascal = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const camel = (s) => s.replace(/[_-](\w)/g, (_, c) => c.toUpperCase());
const SWIFT_RESERVED = new Set(['internal', 'public', 'private', 'default', 'case', 'class', 'struct', 'enum', 'func', 'let', 'var', 'in', 'is', 'as', 'self', 'Type', 'protocol', 'return', 'import', 'operator', 'extension', 'static', 'where', 'while', 'for', 'if', 'else', 'switch', 'repeat', 'do', 'catch', 'try', 'throw', 'throws', 'init', 'deinit', 'subscript', 'typealias', 'nil', 'true', 'false']);
const swiftIdent = (s) => (SWIFT_RESERVED.has(s) ? `\`${s}\`` : s);

let sw = header('//');
sw += `\nimport Foundation\n\n`;
sw += `enum BridgeSchema {\n    static let version = ${schema.version}\n    static let messageHandler = ${JSON.stringify(schema.names.messageHandler)}\n    static let editorGlobal = ${JSON.stringify(schema.names.editorGlobal)}\n}\n\n`;
sw += `enum BridgeErrorCode: String, Codable, Sendable {\n`;
for (const c of schema.errorCodes) sw += `    case ${swiftIdent(camel(c))} = "${c}"\n`;
sw += `}\n\n`;
for (const [name, fields] of Object.entries(schema.types)) {
  const entries = Object.entries(fields);
  sw += `struct ${name}: Codable, Sendable, Equatable {\n`;
  for (const [f, raw] of entries) {
    const t = parseType(raw, `${name}.${f}`);
    sw += `    var ${swiftIdent(f)}: ${swiftType(t)}${t.optional ? ' = nil' : ''}\n`;
  }
  sw += `}\n\n`;
}
sw += `/// A typed bridge method. \`Params\` and \`Result\` are encoded as JSON across the bridge.\n`;
sw += `protocol BridgeMethod {\n    associatedtype Params: Codable & Sendable\n    associatedtype Result: Codable & Sendable\n    static var name: String { get }\n}\n\n`;
for (const group of ['host', 'editor']) {
  const ns = group === 'host' ? 'HostMethods' : 'EditorMethods';
  sw += `/// Methods ${group === 'host' ? 'implemented by the Swift host, called by the editor' : 'implemented by the editor, called by the Swift host'}.\n`;
  sw += `enum ${ns} {\n`;
  for (const [name, m] of methodEntries(group)) {
    const short = pascal(name.slice(group.length + 1));
    sw += `    enum ${short}: BridgeMethod {\n`;
    sw += `        typealias Params = ${swiftType(parseType(m.params, name))}\n`;
    sw += `        typealias Result = ${swiftType(parseType(m.result, name))}\n`;
    sw += `        static let name = "${name}"\n`;
    sw += `    }\n`;
  }
  sw += `    static let allNames: [String] = ${JSON.stringify(methodEntries(group).map(([n]) => n))}\n`;
  sw += `}\n\n`;
}

let stale = false;
for (const [path, content] of [[tsOut, ts], [swiftOut, sw.trimEnd() + '\n']]) {
  const current = existsSync(path) ? readFileSync(path, 'utf8') : '';
  if (current === content) continue;
  if (check) {
    console.error(`Out of date: ${path}. Run \`make gen\`.`);
    stale = true;
  } else {
    writeFileSync(path, content);
    console.log(`wrote ${path.replace(root + '/', '')}`);
  }
}
if (stale) process.exit(1);
